-- Run only against an isolated development database. Fixtures and all mutations roll back.
begin;
create temp table phase2_results(label text);
grant select,insert on phase2_results to authenticated,anon;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is not true then raise exception 'FAILED: %',label;end if;insert into phase2_results values(label);end $$;
create function pg_temp.denied(q text,label text) returns void language plpgsql as $$declare blocked boolean:=false;begin begin execute q;exception when insufficient_privilege or raise_exception then blocked:=true;end;perform pg_temp.ok(blocked,label);end $$;
create function pg_temp.actor(n int,t int default 1) returns void language plpgsql as $$begin
 perform set_config('request.headers',jsonb_build_object('x-tenant-id','f1000000-0000-4000-8000-'||lpad(t::text,12,'0'))::text,true);
 perform set_config('request.jwt.claim.sub','f3000000-0000-4000-8000-'||lpad(n::text,12,'0'),true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','f3000000-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','session_id','f6000000-0000-4000-8000-'||lpad(n::text,12,'0'),'user_metadata',jsonb_build_object('role','admin'))::text,true);
end $$;
insert into public.tenants values('f1000000-0000-4000-8000-000000000001','phase2-a','Synthetic A',true),('f1000000-0000-4000-8000-000000000002','phase2-b','Synthetic B',true);
insert into public.tenant_regions values('f1000000-0000-4000-8000-000000000001','MO','Missouri');
insert into private.relationship_modules(tenant_id,enabled,title) values('f1000000-0000-4000-8000-000000000001',true,'Synthetic connections'),('f1000000-0000-4000-8000-000000000002',true,'Independent workspace');
insert into auth.users(id,email,email_confirmed_at) select ('f3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'phase2-'||n||'@example.test',now() from generate_series(1,6)n;
insert into auth.sessions(id,user_id,created_at,updated_at) select ('f6000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('f3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,now(),now() from generate_series(1,6)n;
insert into private.path_people(tenant_id,id,user_id,display_name) select 'f1000000-0000-4000-8000-000000000001',('f4000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('f3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Synthetic person '||n from generate_series(1,5)n;
insert into private.path_people(tenant_id,id,user_id,display_name) values('f1000000-0000-4000-8000-000000000002','f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','Other tenant identity');
insert into private.workflow_reviewers values('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000004','introductions'),('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000004','privacy'),('f1000000-0000-4000-8000-000000000002','f3000000-0000-4000-8000-000000000006','introductions');
insert into public.user_roles(tenant_id,user_id,role) values('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000006','admin');
insert into private.path_relationships(tenant_id,id,person_a,person_b,context) values
 ('f1000000-0000-4000-8000-000000000001','f5000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000002','PRIVATE_SENTINEL volunteer context'),
 ('f1000000-0000-4000-8000-000000000001','f5000000-0000-4000-8000-000000000002','f4000000-0000-4000-8000-000000000002','f4000000-0000-4000-8000-000000000003','Synthetic professional collaboration'),
 ('f1000000-0000-4000-8000-000000000001','f5000000-0000-4000-8000-000000000003','f4000000-0000-4000-8000-000000000002','f4000000-0000-4000-8000-000000000005','HIDDEN_NETWORK');
insert into public.candidate_profiles(tenant_id,user_id,name,email) values('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','PRIVATE_SENTINEL','phase2-1@example.test');
set local role authenticated;
select pg_temp.actor(1);
select pg_temp.ok(jsonb_array_length(public.path_workspace()->'routes')=0,'Unconfirmed relationships do not produce paths');
update public.candidate_profiles set opportunities_consent=true,consent_version='forged' where user_id=auth.uid();
select pg_temp.ok(exists(select 1 from public.communications_consent where user_id=auth.uid() and permitted and policy_version='2026-11-17' and source='account' and recorded_at=now()),'Profile consent provenance is database-controlled');
select pg_temp.denied($q$insert into public.communications_consent(user_id,purpose,permitted,policy_version,recorded_at) values(auth.uid(),'spotlight',true,'forged',now()+interval '1 year')$q$,'Clients cannot forge consent audit facts');
select public.path_command('{"type":"confirm","edge_id":"f5000000-0000-4000-8000-000000000001","visible":true,"willing":true}');
select pg_temp.actor(2);
select public.path_command('{"type":"confirm","edge_id":"f5000000-0000-4000-8000-000000000001","visible":true,"willing":true}');
select public.path_command('{"type":"confirm","edge_id":"f5000000-0000-4000-8000-000000000002","visible":true,"willing":true}');
select pg_temp.actor(3);
select public.path_command('{"type":"confirm","edge_id":"f5000000-0000-4000-8000-000000000002","visible":true,"willing":true}');
select pg_temp.actor(1);
select pg_temp.ok(jsonb_array_length(public.path_workspace()->'routes')=1 and public.path_workspace()::text not like '%HIDDEN_NETWORK%','Discovery returns only permissioned minimal paths');
select set_config('test.attempt',public.path_command('{"type":"draft","first_edge":"f5000000-0000-4000-8000-000000000001","second_edge":"f5000000-0000-4000-8000-000000000002","note":"PRIVATE_SENTINEL note","opportunity":"Synthetic opportunity"}')::text,true);
select pg_temp.denied($q$select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','submitted','share_context',false))$q$,'Submission requires specific consent');
select pg_temp.actor(4);
select pg_temp.ok(jsonb_array_length(public.path_workspace()->'attempts')=0,'Reviewer cannot read private drafts');
select pg_temp.actor(1);
select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','submitted','share_context',true,'share_email',true));
select pg_temp.actor(2);
select pg_temp.ok(jsonb_array_length(public.path_workspace()->'attempts')=0,'Connector cannot read request early');
select pg_temp.ok((select count(*) from private.path_attempts)=0,'RLS denies early connector direct SQL reads');
select pg_temp.denied($q$select public.path_contacts(current_setting('test.attempt')::uuid)$q$,'Early connector cannot fetch contacts');
select pg_temp.actor(6);
select pg_temp.denied($q$select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','connector_reviewing'))$q$,'Ambient admin and other-tenant reviewer cannot approve');
select pg_temp.ok((select count(*) from public.candidate_profiles)=0,'Ambient administrator cannot read another private profile');
select pg_temp.denied($q$insert into private.workflow_reviewers values('f1000000-0000-4000-8000-000000000001',auth.uid(),'introductions')$q$,'Users cannot self-grant review scope');
select pg_temp.actor(4);
select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','connector_reviewing'));
select pg_temp.actor(3);
select pg_temp.ok(jsonb_array_length(public.path_workspace()->'attempts')=0,'Recipient cannot read before handoff');
select pg_temp.actor(2);
select pg_temp.denied($q$select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','connector_accepted'))$q$,'Acceptance requires explicit action consent');
select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','connector_accepted','consent',true));
select pg_temp.actor(4);
select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','changes_requested','note','PRIVATE_SENTINEL revision feedback'));
select pg_temp.actor(1);
select pg_temp.ok((select count(*) from private.path_consents where attempt_id=current_setting('test.attempt')::uuid and version='2026-11-18.1' and length(wording)>20 and recorded_at is not null)=3,'Original consent wording version and timestamps preserved');
select pg_temp.ok(not ((public.path_workspace()->'attempts'->0->'consents'->0->>'effective')::boolean),'Returned attempt invalidates earlier grants');
select pg_temp.denied($q$update private.path_consents set wording='changed'$q$,'Consent history cannot be edited');
select pg_temp.denied($q$update private.path_attempts set state='introduced'$q$,'Client cannot update state directly');
select set_config('test.old',current_setting('test.attempt'),true);
select set_config('test.attempt',public.path_command(jsonb_build_object('type','revise','attempt_id',current_setting('test.attempt')))::text,true);
select pg_temp.ok((select count(*) from private.path_consents where attempt_id=current_setting('test.attempt')::uuid)=0,'Revision starts with zero inherited consents');
select pg_temp.actor(4);
select pg_temp.denied($q$select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.old'),'to','recipient_reviewing'))$q$,'Superseded attempt cannot advance');
select pg_temp.actor(1,2);
select pg_temp.denied($q$select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','submitted','share_context',true))$q$,'Same user cannot replay request in another tenant');
select pg_temp.ok((select count(*) from private.path_attempts)=0,'Cross-tenant RLS denies reads');
select pg_temp.actor(1);
select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','submitted','share_context',true,'share_email',false));
select pg_temp.actor(4);select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','connector_reviewing'));
select pg_temp.actor(2);select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','connector_accepted','consent',true));
select pg_temp.actor(4);select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','recipient_reviewing'));
select pg_temp.actor(3);select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','recipient_accepted','consent',true,'share_email',true));
select pg_temp.actor(1);select pg_temp.ok(public.path_contacts(current_setting('test.attempt')::uuid)='{}','Email withheld until introduction is made');
select pg_temp.actor(4);select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','introduced','note','PRIVATE_SENTINEL team note'));
select pg_temp.ok(public.path_contacts(current_setting('test.attempt')::uuid)='{}','Reviewer does not receive participant email grants');
select pg_temp.actor(1);select pg_temp.ok(public.path_contacts(current_setting('test.attempt')::uuid)->>'email'='phase2-3@example.test','Only opted-in recipient email revealed after introduction');
select public.path_command(jsonb_build_object('type','followup','attempt_id',current_setting('test.attempt'),'connected',false,'note','PRIVATE_FOLLOWUP_SENTINEL'));
select pg_temp.actor(3);select pg_temp.ok(public.path_contacts(current_setting('test.attempt')::uuid)='{}','Old requester email permission does not carry to revision');
select pg_temp.ok(public.path_workspace()::text not like '%PRIVATE_FOLLOWUP_SENTINEL%','Private follow-up excluded from recipient projection');
select pg_temp.ok(not exists(select 1 from private.path_event_notes where note='PRIVATE_FOLLOWUP_SENTINEL'),'RLS hides private follow-up text');
select pg_temp.actor(1);select public.path_command(jsonb_build_object('type','followup','attempt_id',current_setting('test.attempt'),'connected',true,'note',''));
select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','completed'));
select pg_temp.ok((select state from private.path_attempts where id=current_setting('test.attempt')::uuid)='completed','Full ordered workflow persists with optional follow-up note');

select pg_temp.denied($q$select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.attempt'),'to','submitted','actor','admin'))$q$,'Database rejects client actor spoofing');
select set_config('test.expiry',public.path_command('{"type":"draft","first_edge":"f5000000-0000-4000-8000-000000000001","second_edge":"f5000000-0000-4000-8000-000000000002","note":"Synthetic expiry","opportunity":""}')::text,true);
select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.expiry'),'to','submitted','share_context',true));
reset role;
update private.path_attempts set expires_at=now()-interval '1 minute' where id=current_setting('test.expiry')::uuid;
set local role authenticated;select pg_temp.actor(4);
select pg_temp.denied($q$select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.expiry'),'to','connector_reviewing'))$q$,'Expired request cannot advance before scheduler runs');
reset role;select private.expire_path_attempts();
select pg_temp.ok(exists(select 1 from private.path_attempts where id=current_setting('test.expiry')::uuid and state='expired' and invalidated_at is not null),'Scheduled function expires and invalidates pending attempt');
update private.relationship_modules set enabled=false where tenant_id='f1000000-0000-4000-8000-000000000002';
set local role authenticated;select pg_temp.actor(1,2);
select pg_temp.denied('select public.path_workspace()','Disabled workspace denies access');
select pg_temp.actor(1);select pg_temp.ok(public.path_workspace()->>'title'='Synthetic connections','Disabling second tenant leaves first tenant unchanged');
reset role;delete from private.relationship_modules where tenant_id='f1000000-0000-4000-8000-000000000002';
set local role authenticated;select pg_temp.ok(public.path_workspace()->>'title'='Synthetic connections','Removing optional module leaves primary workspace intact');
reset role;update auth.sessions set not_after=now()-interval '1 minute' where id='f6000000-0000-4000-8000-000000000004';
set local role authenticated;select pg_temp.actor(4);select pg_temp.denied('select public.path_workspace()','Expired Auth session cannot read workflow');
reset role;update auth.sessions set not_after=null where id='f6000000-0000-4000-8000-000000000004';
set local role anon;select pg_temp.denied('select public.path_workspace()','Anonymous workflow RPC denied');
reset role;set local role authenticated;select pg_temp.actor(1);
select set_config('test.deletion',public.path_request_deletion()::text,true);
select pg_temp.actor(2);select pg_temp.denied($q$select public.path_erase(current_setting('test.deletion')::uuid)$q$,'Participant cannot execute privacy-reviewer erasure');
reset role;
