insert into public.events(tenant_id,title,description,starts_at,location,audience,registration_url) values('f1000000-0000-4000-8000-000000000001','PRIVATE_SENTINEL','PRIVATE_SENTINEL',now(),'PRIVATE_SENTINEL','PRIVATE_SENTINEL','https://example.test/PRIVATE_SENTINEL');
insert into public.resource_eligibility(tenant_id,resource_id,state,notes) values('f1000000-0000-4000-8000-000000000001','f9000000-0000-4000-8000-000000000004','MO','PRIVATE_SENTINEL');
