set local role authenticated;select pg_temp.actor(4);
select pg_temp.denied($q$select public.path_erase(current_setting('test.deletion')::uuid)$q$,'Erasure refuses unclassified legacy free text');
reset role;
do $$declare tab text;begin
 foreach tab in array array['tasks','path_attempts','path_event_notes','path_relationships','organizations','employer_conversations','job_needs','evidence_sources','import_batches','import_records','legacy_identity_map','submissions','outcomes','job_postings','resources','events','resource_eligibility','organization_locations','job_locations'] loop
 execute format('insert into private.personal_data_inventory(tenant_id,table_name,row_key,subjects) select tenant_id,$1,private.legacy_personal_key(to_jsonb(r)),array[$2::uuid] from %I.%I r where tenant_id=$3::uuid',case when tab like 'path_%%' then 'private' else 'public' end,tab) using tab,'f3000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001';
 end loop;end $$;

insert into private.retention_holds values('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','Synthetic retention decision pending',current_date+1);
set local role authenticated;select pg_temp.actor(4);
select pg_temp.denied($q$select public.path_erase(current_setting('test.deletion')::uuid)$q$,'Retention hold blocks unreviewed deletion decision');
