set local role authenticated;select pg_temp.actor(4);select public.path_erase(current_setting('test.deletion')::uuid);
reset role;
select pg_temp.ok(not exists(select 1 from private.path_event_notes where tenant_id='f1000000-0000-4000-8000-000000000001'),'Erasure removes associated event notes and private follow-up');
select pg_temp.ok(not exists(select 1 from private.path_attempts where tenant_id='f1000000-0000-4000-8000-000000000001' and (note<>'' or opportunity<>'' or invalidated_at is null)),'Erasure removes attempt text and voids grants');
select pg_temp.ok(not exists(select 1 from public.tasks where tenant_id='f1000000-0000-4000-8000-000000000001' and (notes<>'' or source_record<>'{}' or action like '%PRIVATE_SENTINEL%')),'Erasure scrubs inventoried legacy JSON and text');
select pg_temp.ok(not exists(select 1 from public.candidate_profiles where tenant_id='f1000000-0000-4000-8000-000000000001'),'Private profile erased');
select pg_temp.ok(not exists(select 1 from private.path_events where tenant_id='f1000000-0000-4000-8000-000000000001' and actor_id is not null),'Event facts anonymized while history retained');
select pg_temp.ok(exists(select 1 from private.path_consents where tenant_id='f1000000-0000-4000-8000-000000000001' and person_id is null and wording<>'' and recorded_at is not null),'Anonymized consent facts retain wording and date');
select pg_temp.ok(exists(select 1 from private.path_people where tenant_id='f1000000-0000-4000-8000-000000000002' and user_id='f3000000-0000-4000-8000-000000000001' and active),'Erasure is isolated from independent workspace');
set local role authenticated;select pg_temp.actor(1);select pg_temp.denied($q$select public.path_contacts(current_setting('test.attempt')::uuid)$q$,'Erased data cannot yield contacts');
