do $$declare tab text;leftover boolean;begin
 foreach tab in array array['tasks','path_attempts','path_event_notes','path_relationships','organizations','employer_conversations','job_needs','evidence_sources','import_batches','import_records','legacy_identity_map','submissions','outcomes','job_postings','resources','events','resource_eligibility','organization_locations','job_locations'] loop
 execute format('select exists(select 1 from %I.%I r where tenant_id=$1::uuid and to_jsonb(r)::text like $2)',case when tab like 'path_%%' then 'private' else 'public' end,tab) into leftover using 'f1000000-0000-4000-8000-000000000001','%PRIVATE_SENTINEL%';
 perform pg_temp.ok(not leftover,'No personal sentinel remains in '||tab);
 end loop;end $$;
select jsonb_build_object('passed',count(*),'checks',jsonb_agg(label)) as phase2_result from phase2_results;
rollback;
